CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user');
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated;
GRANT INSERT,UPDATE ON public.economy_config,public.aircraft_types TO authenticated;
CREATE POLICY "Admin inserts economy" ON public.economy_config FOR INSERT TO authenticated WITH CHECK(public.is_admin());
CREATE POLICY "Admin updates economy" ON public.economy_config FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY "Admin inserts aircraft" ON public.aircraft_types FOR INSERT TO authenticated WITH CHECK(public.is_admin());
CREATE POLICY "Admin updates aircraft" ON public.aircraft_types FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE FUNCTION public.admin_players() RETURNS TABLE(user_id uuid,username text,email text,company_name text,icao_code text,balance numeric,fleet_count bigint,joined_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT u.id,coalesce(u.raw_user_meta_data->>'full_name',u.raw_user_meta_data->>'name',split_part(u.email,'@',1)),u.email::text,c.name,c.icao_code,coalesce((SELECT l.balance_after FROM public.company_ledger l WHERE l.company_id=c.id ORDER BY l.id DESC LIMIT 1),0::numeric),(SELECT count(*) FROM public.fleet_aircraft f WHERE f.company_id=c.id),u.created_at FROM auth.users u LEFT JOIN public.companies c ON c.user_id=u.id ORDER BY u.created_at DESC; END $$;
REVOKE ALL ON FUNCTION public.admin_players() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_players() TO authenticated;
CREATE TABLE public.airport_fuel_rules(size integer NOT NULL CHECK(size BETWEEN 1 AND 7),fuel_type text NOT NULL CHECK(fuel_type IN ('100LL','Jet-A')),capacity_gal numeric NOT NULL CHECK(capacity_gal>=0),development_multiplier numeric NOT NULL DEFAULT 0.25 CHECK(development_multiplier>=0),refill_per_hour numeric NOT NULL DEFAULT 0.10 CHECK(refill_per_hour BETWEEN 0 AND 1),PRIMARY KEY(size,fuel_type));
GRANT SELECT,INSERT,UPDATE ON public.airport_fuel_rules TO authenticated;
GRANT ALL ON public.airport_fuel_rules TO service_role;
ALTER TABLE public.airport_fuel_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Players read fuel rules" ON public.airport_fuel_rules FOR SELECT TO authenticated USING(true);
CREATE POLICY "Admin inserts fuel rules" ON public.airport_fuel_rules FOR INSERT TO authenticated WITH CHECK(public.is_admin());
CREATE POLICY "Admin updates fuel rules" ON public.airport_fuel_rules FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
INSERT INTO public.airport_fuel_rules(size,fuel_type,capacity_gal) SELECT s,f,CASE WHEN f='100LL' THEN (ARRAY[500,1000,2500,5000,10000,20000,40000])[s] ELSE (ARRAY[1000,2500,5000,15000,50000,150000,400000])[s] END FROM generate_series(1,7) s CROSS JOIN (VALUES('100LL'),('Jet-A')) x(f);
CREATE TABLE public.airport_fuel_pools(airport_icao text NOT NULL REFERENCES public.airports(icao),fuel_type text NOT NULL CHECK(fuel_type IN ('100LL','Jet-A')),stock_gal numeric NOT NULL DEFAULT 0 CHECK(stock_gal>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(airport_icao,fuel_type));
GRANT SELECT ON public.airport_fuel_pools TO authenticated;
GRANT ALL ON public.airport_fuel_pools TO service_role;
ALTER TABLE public.airport_fuel_pools ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Players read fuel pools" ON public.airport_fuel_pools FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.airport_fuel_capacity(p_airport text,p_fuel text) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.capacity_gal*(1+r.development_multiplier*greatest(0,a.development_level-1)) FROM public.airports a JOIN public.airport_fuel_rules r ON r.size=a.size AND r.fuel_type=p_fuel WHERE a.icao=p_airport $$;
CREATE FUNCTION public.airport_fuel_stock(p_airport text,p_fuel text) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT greatest(0,least(public.airport_fuel_capacity(p_airport,p_fuel),coalesce(p.stock_gal,public.airport_fuel_capacity(p_airport,p_fuel))+greatest(0,extract(epoch FROM now()-coalesce(p.updated_at,now()))/3600)*public.airport_fuel_capacity(p_airport,p_fuel)*r.refill_per_hour)) FROM public.airports a JOIN public.airport_fuel_rules r ON r.size=a.size AND r.fuel_type=p_fuel LEFT JOIN public.airport_fuel_pools p ON p.airport_icao=a.icao AND p.fuel_type=p_fuel WHERE a.icao=p_airport $$;
REVOKE ALL ON FUNCTION public.airport_fuel_capacity(text,text),public.airport_fuel_stock(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.airport_fuel_capacity(text,text),public.airport_fuel_stock(text,text) TO authenticated;
CREATE FUNCTION public.reserve_dispatch_fuel() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fuel text; needed numeric; available numeric; BEGIN SELECT t.fuel_type INTO fuel FROM public.fleet_aircraft f JOIN public.aircraft_types t ON t.id=f.aircraft_type_id WHERE f.id=NEW.aircraft_id; needed:=(NEW.estimate->>'fuel_gal')::numeric; INSERT INTO public.airport_fuel_pools(airport_icao,fuel_type,stock_gal) VALUES(NEW.origin_icao,fuel,public.airport_fuel_stock(NEW.origin_icao,fuel)) ON CONFLICT DO NOTHING; PERFORM 1 FROM public.airport_fuel_pools WHERE airport_icao=NEW.origin_icao AND fuel_type=fuel FOR UPDATE; available:=public.airport_fuel_stock(NEW.origin_icao,fuel); IF needed IS NULL OR needed<0 OR available<needed THEN RAISE EXCEPTION 'Insufficient airport fuel stock'; END IF; UPDATE public.airport_fuel_pools SET stock_gal=available-needed,updated_at=now() WHERE airport_icao=NEW.origin_icao AND fuel_type=fuel; NEW.estimate:=NEW.estimate||jsonb_build_object('fuel_type',fuel,'fuel_reserved_gal',needed); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.reserve_dispatch_fuel() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER reserve_fuel_before_dispatch BEFORE INSERT ON public.flights FOR EACH ROW EXECUTE FUNCTION public.reserve_dispatch_fuel();
CREATE FUNCTION public.return_cancelled_fuel() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fuel text; amount numeric; BEGIN IF NEW.status='CANCELLED' AND OLD.status='DISPATCHED' THEN fuel:=OLD.estimate->>'fuel_type'; amount:=(OLD.estimate->>'fuel_reserved_gal')::numeric; IF fuel IS NOT NULL AND amount IS NOT NULL THEN PERFORM 1 FROM public.airport_fuel_pools WHERE airport_icao=OLD.origin_icao AND fuel_type=fuel FOR UPDATE; UPDATE public.airport_fuel_pools SET stock_gal=least(public.airport_fuel_capacity(OLD.origin_icao,fuel),public.airport_fuel_stock(OLD.origin_icao,fuel)+amount),updated_at=now() WHERE airport_icao=OLD.origin_icao AND fuel_type=fuel; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.return_cancelled_fuel() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER return_fuel_after_cancel AFTER UPDATE OF status ON public.flights FOR EACH ROW EXECUTE FUNCTION public.return_cancelled_fuel();
CREATE FUNCTION public.radar_airport_metrics() RETURNS TABLE(icao text,pax_capacity numeric,pax_stock numeric,avgas_capacity numeric,avgas_stock numeric,jeta_capacity numeric,jeta_stock numeric,operations_7d bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH activity AS (SELECT port,count(*) total FROM (SELECT origin_icao port FROM public.flights WHERE created_at>=now()-interval '7 days' AND status<>'CANCELLED' UNION ALL SELECT destination_icao FROM public.flights WHERE completed_at>=now()-interval '7 days' AND status='COMPLETED') x GROUP BY port) SELECT a.icao,public.passenger_capacity(a.icao),public.passenger_stock(a.icao),public.airport_fuel_capacity(a.icao,'100LL'),public.airport_fuel_stock(a.icao,'100LL'),public.airport_fuel_capacity(a.icao,'Jet-A'),public.airport_fuel_stock(a.icao,'Jet-A'),coalesce(activity.total,0) FROM public.airports a LEFT JOIN activity ON activity.port=a.icao WHERE auth.uid() IS NOT NULL ORDER BY a.icao $$;
REVOKE ALL ON FUNCTION public.radar_airport_metrics() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.radar_airport_metrics() TO authenticated;
COMMENT ON TABLE public.airport_fuel_rules IS 'Simulated game fuel supply; not verified real-world fuel availability. Refill fraction is capacity per hour.';